TEXT ·aesRoundAsm(SB),NOSPLIT,$0-16
	MOVD block+0(FP), R0
	MOVD roundKey+8(FP), R1
	VLD1 (R0), [V0.B16]
	VLD1 (R1), [V1.B16]
	VEOR V2.B16, V2.B16, V2.B16
	AESE V2.B16, V0.B16
	AESMC V0.B16, V0.B16
	VEOR V1.B16, V0.B16, V0.B16
	VST1 [V0.B16], (R0)
	VEOR V0.B16, V0.B16, V0.B16
	VEOR V1.B16, V1.B16, V1.B16
	VEOR V2.B16, V2.B16, V2.B16
	MOVD ZR, R0
	MOVD ZR, R1
	RET

TEXT ·aesFinalRoundAsm(SB),NOSPLIT,$0-16
	MOVD block+0(FP), R0
	MOVD roundKey+8(FP), R1
	VLD1 (R0), [V0.B16]
