	VEOR V2.B16, V2.B16, V2.B16
	AESE V2.B16, V0.B16
	VEOR V1.B16, V0.B16, V0.B16
	VST1 [V0.B16], (R0)
	VEOR V0.B16, V0.B16, V0.B16
	VEOR V1.B16, V1.B16, V1.B16
	VEOR V2.B16, V2.B16, V2.B16
	MOVD ZR, R0
	MOVD ZR, R1
	RET

